  /// 为顶部语言对准备双向 ASR/翻译模型；同一语言对只执行一次。
  Future<Result<void>> _prepareLanguagePair(String left, String right) {
    final languages = [left, right]..sort();
    final pairKey = languages.join('\u0000');
    if (_preparedPairKey == pairKey) {
      return Future.value(const Result.success(null));
    }

    final active = _modelPreparation;
    if (active != null) {
      if (active.pairKey == pairKey) return active.future;
      return active.future.then((_) => _prepareLanguagePair(left, right));
    }

    late final Future<Result<void>> operation;
    operation =
        () async {
          await _engine.unload();
          if (!ref.mounted) return _cancelledModelPreparation();
          final forward = await _engine.prepare(
            fromLanguage: left,
            toLanguage: right,
          );
          if (forward case Failure<void>()) return forward;
          if (!ref.mounted) return _cancelledModelPreparation();

          final reverse = await _engine.prepare(
            fromLanguage: right,
            toLanguage: left,
          );
          if (reverse case Success<void>()) {
            if (!ref.mounted) return _cancelledModelPreparation();
            _preparedPairKey = pairKey;
          }
          return reverse;
        }().whenComplete(() {
          if (identical(_modelPreparation?.future, operation)) {
            _modelPreparation = null;
          }
        });
    _modelPreparation = _LanguagePairPreparation(pairKey, operation);
    return operation;
  }

  Result<void> _cancelledModelPreparation() => const Result.failure(
    AppError(
      code: 'offline.prepare_cancelled',
      message: 'Offline model preparation was cancelled',
    ),
  );

  Future<void> _speak(String text) async {
    try {
      final tts = _tts ??= FlutterTts();
      await tts.speak(text);
    } catch (_) {}
  }
