import Foundation

class WKAIAPIChannelTypeConfigration {


    static func currentAPPChannel() -> WKAIAPIChannelType {
        let appChannel = AppChannelManager.getCurrentChannelType()
        switch appChannel {
        case .WP:
            return .wk
        case .HF:
            return .wk
        case .MINDECHO:
            return .wk
        case .MAXLINGO:
            return .wk
        case .LENOVO:
            return .wk
        case .WAKEOK:
            return .wakeok
        case .HOLIN:
            return .wk
        case .RB:
            return .ruibao
        case .ALAXE:
            return .wk
        case .UNKNOW:
            return .wk
        }
    }


    /// 获取channelType配置，目前除了WP的耳机需要配置hsyk之外，其他都按照项目配置
    /// - Parameter modulType: 模块类型，除了耳机之外其他的都不需要传
    /// - Returns: channelType
    static func channelType(_ moduleType: WKAIAPIModuleType? = nil) -> WKAIAPIChannelType {
        let appChannel = AppChannelManager.getCurrentChannelType()
        if appChannel == .WP {
            return wkChannelType(moduleType)
        } else if appChannel == .WAKEOK {
            return wakeokChannelType(moduleType)
        } else if appChannel == .HOLIN {
            return .holin
        } else if appChannel == .RB {
            return ruibaoChannelType(moduleType)
        } else {
            return wkChannelType(moduleType)
        }
    }


    private static func wkChannelType(_ modulType: WKAIAPIModuleType? = nil) -> WKAIAPIChannelType {
        if modulType == .earphone {
            return .hsyk
        } else {
            return .wk
        }
    }

    private static func wakeokChannelType(_ modulType: WKAIAPIModuleType? = nil) -> WKAIAPIChannelType {
        return .wakeok
    }

    private static func ruibaoChannelType(_ modulType: WKAIAPIModuleType? = nil) -> WKAIAPIChannelType {
        return .ruibao
    }

}

