/// 返回当前 BLE 会话对应的设备记录，不回退到历史设备。
ConnectedDeviceRecord? currentConnectedDeviceRecord(
  BleSessionState session,
  List<ConnectedDeviceRecord> devices,
) {
  final deviceId = session.deviceId;
  if (!session.isConnected || deviceId == null || deviceId.isEmpty) {
    return null;
  }
  for (final device in devices) {
    if (device.deviceId == deviceId) return device;
  }
  return null;
}

/// 原生眼镜首页是否为当前设备展示 AI 联网指引。
bool supportsAiNetworkGuidance(ConnectedDeviceRecord? device) {
  if (device == null) return false;
  return (device.boundProductId == _akwGlassesProductId &&
          device.boundChipType == _akwChipType) ||
      device.boundProductId == _audioGlassesProductId;
}

/// 返回当前已连接设备可用于必须具备业务 code 的云端能力的身份记录。
///
/// 设备作用域能力绝不能借用历史设备的身份，因此当前会话未连接、没有设备 ID
/// 或记录缺少 `deviceCode` 时一律返回 `null`。
ConnectedDeviceRecord? currentBoundDeviceIdentity(
  BleSessionState session,
  List<ConnectedDeviceRecord> devices,
) {
  final device = currentConnectedDeviceRecord(session, devices);
  return device?.hasBoundDeviceCode == true ? device : null;
}
