import 'dart:convert';

/// Debug network log formatting with credential redaction and size limits.
abstract final class NetworkLogSanitizer {
  static const _maxValueLength = 2048;
  static const _sensitiveKeys = {
    'authorization',
    'proxy-authorization',
    'token',
    'utoken',
    'apikey',
    'api-key',
    'password',
    'cookie',
    'set-cookie',
  };

  static String headers(Map<String, dynamic> headers) {
    final entries = headers.entries.toList()
      ..sort((a, b) => a.key.toLowerCase().compareTo(b.key.toLowerCase()));
    return '{${entries.map((entry) {
      final value = _isSensitive(entry.key) ? '<redacted>' : _truncate(entry.value.toString());
      return '${entry.key}: $value';
    }).join(', ')}}';
  }

  static String body(Object? body) {
    if (body == null) return '<empty>';
    if (body is Stream) return '<stream>';
    return _truncate(_encodeRedacted(body));
  }

  static String sseLine(String line) {
    final trimmed = line.trim();
    final hasDataPrefix = trimmed.startsWith('data:');
    final payload = hasDataPrefix
        ? trimmed.substring('data:'.length).trim()
        : trimmed;
    if (payload.isEmpty || !payload.startsWith('{')) {
      return _truncate(trimmed);
    }
    try {
      final redacted = _redact(jsonDecode(payload));
      final encoded = jsonEncode(redacted);
      return _truncate(hasDataPrefix ? 'data: $encoded' : encoded);
    } catch (_) {
      return _truncate(trimmed);
    }
  }

